+  ino: number;
+  readBytes: number;
+  mtimeMs: number;
+  ctimeMs: number;
+  terminalLiveOutputDigest: string | null;
+  terminalGeneration: number | null;
+  frames: ManagedHostRunOutputFrame[];
+  trailing: Buffer;
+  monotonicSequences: boolean;
+  lastSequence: number | null;
+  lastAccessAt: number;
